{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In patients, cytotoxic paclitaxel tissue levels were measured in brain tumors, indicating that a disrupted BBB in the tumor vicinity can permit better penetration of a P-gp substrate; this supports the possibility of meaningful CNS access for the query under glioma conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Radiolabeled paclitaxel was detectable in the brain after intravenous administration, showing that even a strong P-gp substrate can achieve some brain entry; the query's smaller size and higher lipophilicity relative to paclitaxel support greater access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "CMT-3, a lipophilic modified tetracycline, showed brain accumulation of 4 µg/g in rats, demonstrating that a lipophilic, non-sugar small molecule can cross the BBB; the query's anthracycline aglycone provides comparable lipophilic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Mithramycin, a large polyglycosylated antitumor antibiotic, showed poor CSF penetration in monkeys; however, its much larger size and multiple sugar chains limit transfer to the smaller, monoglycosylated query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is idarubicin, an anthracycline known to cross the BBB more effectively than other anthracyclines due to its 4-demethoxy substitution and increased lipophilicity. Although the physicochemical prior is unfavorable and several large glycoside analogues show poor CNS penetration, the brain-tumor condition and evidence that P-gp substrates can achieve tumor penetration support meaningful CNS access.",
  "evidence_gaps": [
    "No direct idarubicin CSF or brain measurement is included in the provided evidence; the closest analogues are structurally distant.",
    "The magnitude of CNS exposure in glioma patients is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

